/// Create routes for state transitions.
pub fn create_processing_job_transition_routes(service: Arc<ProcessingJobService>) -> Router {
    use axum::routing::post;

    Router::new()
        .route("/processing_jobs/:id/transitions/start", post(start_transition))
        .route("/processing_jobs/:id/transitions/complete", post(complete_transition))
        .route("/processing_jobs/:id/transitions/fail", post(fail_transition))
        .route("/processing_jobs/:id/transitions/cancel_pending", post(cancel_pending_transition))
        .route("/processing_jobs/:id/transitions/cancel_running", post(cancel_running_transition))
        .route("/processing_jobs/:id/transitions/retry", post(retry_transition))
        .route("/processing_jobs/:id/transitions/reprocess", post(reprocess_transition))
        .with_state(service)
        .layer(axum::middleware::from_fn(backbone_core::http::correlation_middleware))
}

